const long long M = 1000000007;

struct Co {
    long long v;
    Co(long long x = 0) {
        v = (x % M + M) % M;
    }
    Co pow(long long n) const {
        Co a = *this;
        Co res(1);
        while (n > 0) {
            if (n & 1) res *= a;
            a = a * a;
            n >>= 1;
        }
        return res;
    }
};

ostream& operator<<(ostream& os, const Co& c) {
    os << c.v;
    return os;
}

Co operator+(const Co& a, const Co& b) {
    return Co(a.v + b.v);
}
Co& operator+=(Co& a, const Co& b) {
    a = a + b;
    return a;
}
Co operator-(const Co& a, const Co& b) {
    return Co(a.v - b.v);
}
Co& operator-=(Co& a, const Co& b) {
    a = a - b;
    return a;
}
Co operator*(const Co& a, const Co& b) {
    return Co(a.v * b.v);
}
Co& operator*=(Co& a, const Co& b) {
    a = a * b;
    return a;
}
Co operator/(const Co& a, const Co& b) {
    return a * b.pow(M - 2);
}
Co& operator/=(Co& a, const Co& b) {
    a = a / b;
    return a;
}

struct Env {
    size_t k;
    size_t d;
    vector<vector<optional<Co>>> memo;

    Co need(size_t n) {
        if (memo[n][0].has_value()) {
            return memo[n][0].value();
        }
        Co sum(0);
        for (size_t i = 1; i <= k; ++i) {
            if (n >= i) {
                if (i >= d) sum += all(n - i);
                else sum += need(n - i);
            }
        }
        memo[n][0] = sum;
        return sum;
    }

    Co all(size_t n) {
        if (memo[n][1].has_value()) {
            return memo[n][1].value();
        }
        Co sum(0);
        for (size_t i = 1; i <= k; ++i) {
            if (n >= i) sum += all(n - i);
        }
        memo[n][1] = sum;
        return sum;
    }
};

