use std::io::{stdin, Read, StdinLock};
use std::str::FromStr;
use std::iter::FromIterator;

#[allow(unused_macros)]
macro_rules! vecs {
    ($init:expr; $($dim:expr);*) => {
        vecs!($($dim);* => $init)
    };
    ($head:expr; $($tail:expr);* => $init:expr) => {
        vec![vecs!($($tail);* => $init); $head]
    };
    ($head:expr => $init:expr) => {
        vec![$init; $head]
    };
}

fn main() {
    let cin = stdin();
    let mut scan = Scanner::new(cin.lock());
    let n = scan.read::<usize>();
    let k = scan.read::<usize>();
    let d = scan.read::<usize>();
    let mut env = Env {k: k, d: d, memo: vecs![None;n+1;2]};
    env.memo[0][1] = Some(1.into());
    println!("{}", env.need(n));
}

struct Env {
    k: usize,
    d: usize,
    memo: Vec<Vec<Option<Co>>>
}

impl Env {
    fn need(&mut self, n: usize) -> Co {
        if let Some(d) = self.memo[n][0] {
            return d;
        }
        let mut sum = Co(0);
        for i in 1..self.k+1 {
            if n>=i {
                if i>=self.d {sum += self.all(n-i);}
                else {sum += self.need(n-i);}
            }
        }
        self.memo[n][0] = Some(sum);
        sum
    }

    fn all(&mut self, n: usize) -> Co {
        if let Some(d) = self.memo[n][1] {
            return d;
        }
        let mut sum = Co(0);
        for i in 1..self.k + 1 {
            if n>=i {sum += self.all(n-i);}
        }
        self.memo[n][1] = Some(sum);
        sum
    }
}

